// Each cell retains its count and period in a keyboard- and touch-accessible button.
export function DomainHeatmap({
  onSelect,
}: {
  onSelect: (category: string) => void;
}) {
  const rows = domainActivity();
  const max = Math.max(...rows.flatMap((r) => r.values));
  return (
    <div className="viz-heatmap">
      <div className="viz-heat-scale">
        <span>领域 / 两小时分桶</span>
        <span>
          低 <i /> 高
        </span>
      </div>
      {rows.map((row) => (
        <div className="viz-heat-row" key={row.category}>
          <button
            className="viz-domain-label"
            onClick={() => onSelect(row.category)}
          >
            {row.category}
          </button>
          <div>
            {row.values.map((v, i) => (
              <button
                key={i}
                style={{
                  background: `rgba(71,118,238,${0.1 + (v / max) * 0.86})`,
                }}
                aria-label={`${row.category}，第${i + 1}个两小时窗口，${v}条`}
                title={`${row.category} · 窗口 ${i + 1} · ${v} 条`}
                onClick={() => onSelect(row.category)}
              />
            ))}
          </div>
        </div>
      ))}
      <div className="viz-heat-times">
        <span>昨 14:30</span>
        <span>02:30</span>
        <span>今 14:30</span>
      </div>
      <p className="viz-note">
        选定话题讨论量分布 · 固定样本分桶 · 点击领域深入分析
      </p>
    </div>
  );
}

// Aggregate only the visible record collection, including its current withdrawal filter.
export function RecordDistribution({
  records,
  onSource,
}: {
  records: Article[];
  onSource?: (source: string) => void;
}) {
  const sources = [...new Set(records.map((a) => a.source))];
  const sentiments = [
    { name: "负面", color: chartColors.red },
    { name: "中性", color: chartColors.blue },
    { name: "正面", color: chartColors.teal },
  ];
  return (
    <div className="viz-records">
      <div className="viz-legend">
        {sentiments.map((s) => (
          <span key={s.name}>
            <i style={{ background: s.color }} />
            {s.name}
          </span>
        ))}
        <small>{records.length} 条可查记录</small>
      </div>
      {sources.map((source) => {
        const list = records.filter((a) => a.source === source);
        return (
          <button
            className="viz-record-row"
            key={source}
            onClick={() => onSource?.(source)}
            disabled={!onSource}
          >
            <span>{source}</span>
            <div className="viz-stacked-bar">
              {sentiments.map((s) => {
                const count = list.filter((a) => a.sentiment === s.name).length;
                return (
                  <span
                    key={s.name}
                    style={{
                      width: `${(count / Math.max(records.length, 1)) * 100}%`,
                      background: s.color,
                    }}
                    title={`${s.name} ${count} 条`}
                  />
                );
              })}
            </div>
            <strong>{list.length}</strong>
          </button>
        );
      })}
      {!sources.length && <EmptyState />}
      <p className="viz-note">
        按当前可查记录计算；撤回后与历史快照计数的差额可追溯
      </p>
    </div>
  );
}

// The graph uses actual document IDs and report memberships; unavailable originals never leak into labels.
