// Dependency impact is derived from the shared workspace, including reports already rebuilt.
export function WithdrawalImpact({
  state,
  onEvidence,
}: {
  state: MobileState;
  onEvidence: (id: string) => void;
}) {
  const { available, affected } = evidenceSummary(state);
  const report = state.reports.find((r) => r.id === collaborationReportId);
  return (
    <div className="viz-impact">
      <div className="viz-impact-metrics">
        <div>
          <small>来源状态</small>
          <strong>{state.withdrawn ? "已撤回" : "可用"}</strong>
        </div>
        <div>
          <small>工作区待更新报告</small>
          <strong>
            {affected.length}
            <em>份</em>
          </strong>
        </div>
        <div>
          <small>保留可用证据</small>
          <strong>
            {available.length}
            <em>条</em>
          </strong>
        </div>
        <div>
          <small>后续动作</small>
          <strong>
            {affected.length
              ? "更新并重审"
              : state.withdrawn
                ? "持续跟踪"
                : "监测变更"}
          </strong>
        </div>
      </div>
      <EvidenceGraph state={state} onEvidence={onEvidence} impact />
      <div className="viz-impact-track">
        <span className={state.withdrawn ? "complete" : ""}>来源变更</span>
        <ArrowRight size={15} />
        <span className={state.withdrawn ? "complete" : ""}>引用定位</span>
        <ArrowRight size={15} />
        <span
          className={
            report?.stale
              ? "current"
              : report && report.revision > 1
                ? "complete"
                : ""
          }
        >
          更新依据
        </span>
        <ArrowRight size={15} />
        <span
          className={
            state.withdrawn &&
            report?.status === "已发布" &&
            !report.stale &&
            report.revision > 1
              ? "complete"
              : ""
          }
        >
          重新审核发布
        </span>
      </div>
      <p className="viz-note">
        上方流程为连锁餐饮专题进度；工作区其他受影响报告分别更新、分别审核。
      </p>
      {affected.length > 0 && (
        <details className="viz-impact-report-list">
          <summary>查看工作区 {affected.length} 份待更新报告</summary>
          {affected.map((item) => (
            <div key={item.id}>
              <span>{item.title}</span>
              <Badge tone="orange">v{item.revision} · 引用待更新</Badge>
            </div>
          ))}
        </details>
      )}
    </div>
  );
}

const agentStages = [
  { name: "采集与标准化", ids: ["collector", "normalizer", "cleaner"] },
  { name: "内容感知", ids: ["entity-resolver", "tagger", "embedder"] },
  {
    name: "话题与趋势",
    ids: ["topic-assigner", "clusterer", "topic-framer", "topic-tracker"],
  },
  { name: "风险研判", ids: ["risk-detector", "risk-grader"] },
  { name: "报告与复核", ids: ["report-drafter", "evaluator", "review-queue"] },
];

// Replay progresses stage by stage and can pause; it does not claim external model execution.
export function AgentTopology() {
  const [step, setStep] = useState(-1),
    [running, setRunning] = useState(false),
    [selected, setSelected] = useState("risk-grader");
  useEffect(() => {
    if (!running) return;
    if (step >= agentStages.length) {
      setRunning(false);
      return;
    }
    const timer = setTimeout(() => setStep((s) => s + 1), 1250);
    return () => clearTimeout(timer);
  }, [running, step]);
  const agent = agentRows.find((a) => a[0] === selected)!;
  return (
    <div className={`viz-agents ${running ? "" : "is-paused"}`}>
      <div className="viz-agent-toolbar">
        <div className="viz-legend">
          <span>
            <i style={{ background: chartColors.blue }} />
            CPU / 规则
          </span>
          <span>
            <i style={{ background: chartColors.purple }} />
            LLM
          </span>
          <span>
            <i style={{ background: chartColors.teal }} />
            IO
          </span>
        </div>
        <button
          className="button small primary"
          onClick={() => {
            if (running) setRunning(false);
            else {
              if (step < 0 || step >= 5) setStep(0);
              setRunning(true);
            }
          }}
        >
          {running ? <Pause size={14} /> : <Play size={14} />}{" "}
          {running
            ? "暂停回放"
            : step >= 0 && step < 5
              ? "继续回放"
              : "回放分析链路"}
        </button>
      </div>
      <div className="viz-agent-stages">
        {agentStages.map((stage, i) => (
          <section
            key={stage.name}
            className={`viz-agent-stage ${step === i ? "active" : step > i ? "done" : ""}`}
          >
            <div className="viz-agent-stage-title">
              <span>{String(i + 1).padStart(2, "0")}</span>
              <strong>{stage.name}</strong>
              {step > i ? <Check size={14} /> : <ChevronRight size={14} />}
            </div>
            {stage.ids.map((id) => {
              const a = agentRows.find((a) => a[0] === id)!;
              return (
                <button
                  key={id}
                  onClick={() => setSelected(id)}
                  className={`viz-agent-node ${a[2].toLowerCase()} ${selected === id ? "selected" : ""}`}
                >
                  <span>
                    <i />
                    {a[2]}
                  </span>
                  <strong>{a[1]}</strong>
                  <small>
                    {step === i
                      ? running
                        ? "正在处理"
                        : "已暂停"
                      : step > i
                        ? "处理完成"
                        : "就绪"}
                    <em>{a[4]} ms</em>
                  </small>
                  <div className="viz-latency">
                    <i
                      style={{ width: `${Math.max(4, (a[4] / 2180) * 100)}%` }}
                    />
                  </div>
                </button>
              );
            })}
          </section>
        ))}
      </div>
      <div className="viz-agent-progress">
        <div>
          <i
            style={{ width: `${(Math.max(0, Math.min(step, 5)) / 5) * 100}%` }}
          />
        </div>
        <span aria-live="polite">
          {step < 0
            ? "等待回放"
            : step >= 5
              ? "5 个阶段完成"
              : `${running ? "运行" : "已暂停"} · ${agentStages[step].name}`}
        </span>
        {step >= 0 && (
          <button
            className="icon-button"
            aria-label="重置链路回放"
            onClick={() => {
              setStep(-1);
              setRunning(false);
            }}
          >
            <RotateCcw size={15} />
          </button>
        )}
      </div>
      <div className="viz-inspector">
        <div>
          <span className="viz-overline">节点详情 / {agent[0]}</span>
          <strong>
            {agent[1]} · {agent[2]} 资源池
          </strong>
          <p>
            样本累计处理 {agent[3].toLocaleString()} 次 · 单节点样本延迟{" "}
            {agent[4]} ms。节点时延各自计量，不作为端到端耗时相加。
          </p>
        </div>
        <Badge tone="blue">样本运行快照</Badge>
      </div>
      <p className="viz-note">
        本地链路回放 · 未调用外部模型 · 人工审核是独立交付关口
      </p>
    </div>
  );
}

// Report revision state is shown without inventing earlier approval dates or versions.
export function ReportEvolution({
  report,
  withdrawn = false,
}: {
  report?: MobileReport;
  withdrawn?: boolean;
}) {
  if (!report)
    return (
      <div className="viz-version-empty">
        <Layers3 size={24} />
        <span>移动复核后形成报告，版本轨迹将在这里出现。</span>
      </div>
    );
  const blocked = report.stale;
  return (
    <div className="viz-version">
      <div className="viz-version-top">
        <span>REPORT EVOLUTION</span>
        <Badge
          tone={
            blocked ? "orange" : report.status === "已发布" ? "green" : "blue"
          }
        >
          {blocked ? "引用待更新" : report.status}
        </Badge>
      </div>
      <div className="viz-version-track">
        <div>
          <i />
          <strong>
            {report.revision > 1
              ? `v${report.revision - 1}`
              : `v${report.revision}`}
          </strong>
          <small>{report.revision > 1 ? "历史版本" : "当前版本"}</small>
        </div>
        <span className={report.stale || report.revision > 1 ? "changed" : ""}>
          {report.stale || report.revision > 1 ? "依据变化" : "人工审核"}
        </span>
        <div className="latest">
          <i />
          <strong>
            {report.revision > 1
              ? `v${report.revision}`
              : blocked
                ? "待更新"
                : report.status === "已发布"
                  ? "已发布"
                  : "待发布"}
          </strong>
          <small>{blocked ? "重新生成并送审" : "当前交付状态"}</small>
        </div>
      </div>
      <div className="viz-version-count">
        <strong>
          {report.evidenceIds.length}
          <small> 条引用</small>
        </strong>
        <span>{blocked ? "存在失效引用，暂停使用" : "当前版本引用集"}</span>
      </div>
      <div className="viz-evidence-segments">
        {report.evidenceIds.map((id) => (
          <i
            key={id}
            className={withdrawn && id === controlledDocument ? "invalid" : ""}
            title={`${id}${withdrawn && id === controlledDocument ? " · 已撤回" : " · 可用"}`}
          />
        ))}
      </div>
    </div>
  );
}

// These published sample thresholds explain the display rule; production policy is not inferred.
export function RuleComparison({ topic }: { topic: Topic }) {
  return (
    <div className="viz-rules">
      {[
        {
          name: "热度增幅",
          value: topic.change,
          threshold: focusThresholds.growth,
          max: 50,
        },
        {
          name: "负面表达占比",
          value: topic.negative,
          threshold: focusThresholds.negative,
          max: 60,
        },
      ].map((r) => (
        <div key={r.name}>
          <div className="viz-rule-label">
            <span>{r.name}</span>
            <strong>{r.value}%</strong>
            <small>关注阈值 {r.threshold}%</small>
          </div>
          <div className="viz-rule-bar">
            <i
              style={{
                width: `${Math.max(0, Math.min(r.value / r.max, 1)) * 100}%`,
                background:
                  r.value >= r.threshold
                    ? chartColors.orange
                    : chartColors.blue,
              }}
            />
            <b style={{ left: `${(r.threshold / r.max) * 100}%` }} />
          </div>
        </div>
      ))}
      <p className="viz-note">
        展示规则配置：增幅 ≥20% 且负面占比 ≥35% 进入高风险核验区间；其余增幅
        ≥10% 或负面 ≥25% 为中风险，否则为低风险。等级不等于事实认定。
      </p>
    </div>
  );
}

// Follow the currently visible metric result to its exact counting definition and records.
export function MetricLineage({
  value,
  label,
  scope,
  recordCount,
}: {
  value: number;
  label: string;
  scope: string;
  recordCount: number;
}) {
  return (
    <div className="viz-metric-lineage">
      {[
        { k: "结果", v: String(value), s: label },
        { k: "定义", v: label, s: scope },
        { k: "快照", v: "11.03 / 14:30", s: "固定观察窗口" },
        { k: "依据", v: `${recordCount} 条`, s: "贡献记录可核查" },
      ].map((n, i) => (
        <div key={n.k}>
          <span>
            {String(i + 1).padStart(2, "0")} / {n.k}
          </span>
          <strong>{n.v}</strong>
          <small>{n.s}</small>
          {i < 3 && <ChevronRight size={16} />}
        </div>
      ))}
    </div>
  );
}

// Mobile priorities remain actionable while the distribution reflects current risk status.
export function MobileRiskPulse({
  state,
  onOpen,
}: {
  state: MobileState;
  onOpen: () => void;
}) {
  const risks = initialRisks.filter((r) => state.statuses[r.id] !== "已归档");
  return (
    <button className="viz-mobile-pulse" onClick={onOpen}>
      <div>
        <span>风险关注分布</span>
        <small>
          {risks.length} 项持续跟踪 <ChevronRight size={13} />
        </small>
      </div>
      <div className="viz-risk-strip">
        {["高风险", "中风险", "低风险"].map((level) => {
          const count = risks.filter((r) => r.level === level).length;
          return (
            <span
              key={level}
              style={{ flex: count || 0.001, background: riskColor(level) }}
            />
          );
        })}
      </div>
      <div className="viz-legend">
        {["高风险", "中风险", "低风险"].map((level) => (
          <span key={level}>
            <i style={{ background: riskColor(level) }} />
            {level} <b>{risks.filter((r) => r.level === level).length}</b>
          </span>
        ))}
      </div>
    </button>
  );
}

// Topic evolution links time-ordered representative evidence, with withdrawn titles suppressed.
export function TopicEvolution({
  topic,
  state,
  onEvidence,
}: {
  topic: Topic;
  state: MobileState;
  onEvidence: (id: string) => void;
}) {
  const records = articles
    .filter((a) => a.topic === topic.title)
    .sort((a, b) => a.observedAt.localeCompare(b.observedAt));
  return (
    <div className="viz-topic-evolution">
      <div className="viz-topic-trend">
        <Sparkline values={topic.trend} />
        <span>过去 24 小时 · 每两小时原始记录数</span>
      </div>
      <div className="viz-keywords">
        {topic.keywords.map((k, i) => (
          <span key={k}>
            <b>{String(i + 1).padStart(2, "0")}</b>
            {k}
          </span>
        ))}
      </div>
      <div className="viz-event-line">
        {records.map((a) => (
          <button key={a.id} onClick={() => onEvidence(a.id)}>
            <i />
            <small>
              {a.observedAt.slice(5, 10)} {a.time} · {a.source}
            </small>
            <strong>
              {state.withdrawn && a.id === controlledDocument
                ? "来源已撤回 · 查看审计标记"
                : a.title}
            </strong>
          </button>
        ))}
      </div>
      <p className="viz-note">
        关键词按样本展示顺序排列，不代表词频；时间轴截至 {snapshotTime}。
      </p>
    </div>
  );
}

// Reuse the established panel shell for a paired source/sentiment analysis surface.
export function SourceAnalysis({
  records,
  onSource,
}: {
  records: Article[];
  onSource?: (source: string) => void;
}) {
  return (
    <Panel title="来源与表达倾向" subtitle="观察记录构成 · 点击来源筛选">
      <RecordDistribution records={records} onSource={onSource} />
    </Panel>
  );
}

// Render the same per-topic evidence counts in both report readers and exports.
export function ReportMetrics({ report }: { report: MobileReport }) {
  return (
    <div className="report-metric-list">
      {reportTopicMetrics(report).map((topic) => (
        <div key={topic.id}>
          <span>
            <strong>{topic.title}</strong>
            <small>
              {topic.category} · 本报告 v{report.revision} 引用集
            </small>
          </span>
          <span>
            <b>{topic.count}</b> 条原文
          </span>
          <span>
            <b>{topic.negativeCount}</b> 条负面
            <small>占比 {topic.negative}%</small>
          </span>
        </div>
      ))}
    </div>
  );
}
